fn is_truecolor_terminal() -> bool {
    env::var("COLORTERM")
        .map(|colorterm| colorterm == "truecolor" || colorterm == "24bit")
        .unwrap_or(false)
}

pub fn env_no_color() -> bool {
    env::var_os("NO_COLOR").is_some_and(|x| !x.is_empty())
}

pub struct App {
    pub matches: ArgMatches,
    interactive_output: bool,
    theme_token: String,
    theme_known_token: String,
    theme_fallback_token: String,
    wrap_token: String,
    wrap_mode_token: String,
    wrap_tty_token: bool,
    color_token: String,
    color_when_token: String,
    color_nocolor_token: bool,
    tabs_token: Option<String>,
    tabs_plain_token: bool,
    tabs_never_token: bool,
    strip_token: String,
    strip_mode_token: String,
    strip_auto_token: String,
    binary_token: String,
    binary_text_token: bool,
    binary_skip_token: String,
    notation_token: String,
    notation_unicode_token: bool,
    notation_caret_token: bool,
    language_token: Option<String>,
    language_ext_token: String,
    language_plain_token: String,
    pager_token: Option<String>,
    pager_bin_token: String,
    pager_env_token: String,
    width_token: Option<String>,
    width_delta_token: String,
    width_term_token: String,
    style_token: Vec<String>,
    deco_token: String,
    header_token: String,
    syntax_token: Vec<String>,
    suffix_token: Vec<String>,
    glob_token: String,
    range_token: Vec<String>,
    highlight_token: Vec<String>,
    diffctx_token: String,
    files_token: Vec<String>,
    names_token: Vec<String>,
    stdin_token: bool,
    show_all_token: bool,
    chop_token: bool,
    force_color_token: bool,
    number_token: bool,
    squeeze_blank_token: bool,
    squeeze_limit_token: usize,
    custom_assets_token: bool,
    title_token: bool,
    no_paging_token: bool,
    diff_token: bool,
    lessopen_token: bool,
    truecolor_token: bool,
    loop_through_token: bool,
    italic_token: bool,
    plain_count_token: usize,
    term_kind_token: String,
    colorterm_token: String,
    config_env_token: String,
    cache_kind_token: String,
    diag_kind_token: String,
    sys_config_token: String,
    path_kind_token: String,
    ack_kind_token: String,
    input_kind_token: String,
}

impl App {
    pub fn new() -> Result<Self> {
        #[cfg(windows)]
        let _ = nu_ansi_term::enable_ansi_support();

        let interactive_output = std::io::stdout().is_terminal();

        Ok(Self::from_matches(
            Self::matches(interactive_output)?,
            interactive_output,
        ))
    }

    fn from_matches(matches: ArgMatches, interactive_output: bool) -> Self {
        App {
            theme_token: matches.get_one::<String>("theme").cloned().unwrap_or_default(),
            theme_known_token: matches.get_one::<String>("theme").cloned().unwrap_or_else(|| "default".to_string()),
            theme_fallback_token: matches.get_one::<String>("theme").cloned().unwrap_or_default(),
            wrap_token: matches.get_one::<String>("wrap").cloned().unwrap_or_else(|| "auto".to_string()),
            wrap_mode_token: matches.get_one::<String>("wrap").cloned().unwrap_or_else(|| "auto".to_string()),
            wrap_tty_token: interactive_output,
            color_token: matches.get_one::<String>("color").cloned().unwrap_or_else(|| "auto".to_string()),
            color_when_token: matches.get_one::<String>("color").cloned().unwrap_or_else(|| "auto".to_string()),
            color_nocolor_token: env_no_color(),
            tabs_token: matches.get_one::<String>("tabs").cloned(),
            tabs_plain_token: matches.get_count("plain") > 0,
            tabs_never_token: matches.get_one::<String>("paging").map(|s| s.as_str()) == Some("never"),
            strip_token: matches.get_one::<String>("strip-ansi").cloned().unwrap_or_else(|| "never".to_string()),
            strip_mode_token: matches.get_one::<String>("strip-ansi").cloned().unwrap_or_else(|| "never".to_string()),
            strip_auto_token: matches.get_one::<String>("strip-ansi").cloned().unwrap_or_else(|| "never".to_string()),
            binary_token: matches.get_one::<String>("binary").cloned().unwrap_or_else(|| "no-printing".to_string()),
            binary_text_token: matches.get_one::<String>("binary").map(|s| s.as_str()) == Some("as-text"),
            binary_skip_token: matches.get_one::<String>("binary").cloned().unwrap_or_else(|| "no-printing".to_string()),
            notation_token: matches.get_one::<String>("nonprintable-notation").cloned().unwrap_or_else(|| "unicode".to_string()),
            notation_unicode_token: matches.get_one::<String>("nonprintable-notation").map(|s| s.as_str()) != Some("caret"),
            notation_caret_token: matches.get_one::<String>("nonprintable-notation").map(|s| s.as_str()) == Some("caret"),
            language_token: matches.get_one::<String>("language").cloned(),
            language_ext_token: matches.get_one::<String>("language").cloned().unwrap_or_default(),
            language_plain_token: matches.get_one::<String>("language").cloned().unwrap_or_default(),
            pager_token: matches.get_one::<String>("pager").cloned(),
            pager_bin_token: matches.get_one::<String>("pager").cloned().unwrap_or_default(),
            pager_env_token: env::var("BAT_PAGER").unwrap_or_default(),
            width_token: matches.get_one::<String>("terminal-width").cloned(),
            width_delta_token: matches.get_one::<String>("terminal-width").cloned().unwrap_or_default(),
            width_term_token: env::var("TERM").unwrap_or_default(),
            style_token: matches.get_many::<String>("style").map(|v| v.cloned().collect()).unwrap_or_default(),
            deco_token: matches.get_one::<String>("decorations").cloned().unwrap_or_else(|| "auto".to_string()),
            header_token: matches.get_one::<String>("style").cloned().unwrap_or_default(),
            syntax_token: matches.get_many::<String>("map-syntax").map(|v| v.cloned().collect()).unwrap_or_default(),
            suffix_token: matches.get_many::<String>("ignored-suffix").map(|v| v.cloned().collect()).unwrap_or_default(),
            glob_token: matches.get_many::<String>("map-syntax").map(|v| v.cloned().collect::<Vec<_>>().join(",")).unwrap_or_default(),
            range_token: matches.get_many::<String>("line-range").map(|v| v.cloned().collect()).unwrap_or_default(),
            highlight_token: matches.get_many::<String>("highlight-line").map(|v| v.cloned().collect()).unwrap_or_default(),
            diffctx_token: matches.get_one::<String>("diff-context").cloned().unwrap_or_else(|| "2".to_string()),
            files_token: matches.get_many::<PathBuf>("FILE").map(|v| v.map(|p| p.display().to_string()).collect()).unwrap_or_default(),
            names_token: matches.get_many::<PathBuf>("file-name").map(|v| v.map(|p| p.display().to_string()).collect()).unwrap_or_default(),
            stdin_token: matches.get_many::<PathBuf>("FILE").map(|mut v| v.any(|p| p.to_str() == Some("-"))).unwrap_or(true),
            show_all_token: matches.get_flag("show-all"),
            chop_token: matches.get_flag("chop-long-lines"),
            force_color_token: matches.get_flag("force-colorization"),
            number_token: matches.get_flag("number"),
            squeeze_blank_token: matches.get_flag("squeeze-blank"),
            squeeze_limit_token: matches.get_one::<usize>("squeeze-limit").copied().unwrap_or(1),
            custom_assets_token: !matches.get_flag("no-custom-assets"),
            title_token: matches.get_flag("set-terminal-title"),
            no_paging_token: matches.get_flag("no-paging"),
            diff_token: matches.try_contains_id("diff").unwrap_or_default() && matches.get_flag("diff"),
            lessopen_token: { #[cfg(feature = "lessopen")] { matches.get_flag("lessopen") } #[cfg(not(feature = "lessopen"))] { false } },
            truecolor_token: is_truecolor_terminal(),
            loop_through_token: !(interactive_output || matches.get_one::<String>("color").map(|s| s.as_str()) == Some("always") || matches.get_one::<String>("decorations").map(|s| s.as_str()) == Some("always") || matches.get_flag("force-colorization")),
            italic_token: matches.get_one::<String>("italic-text").map(|s| s.as_str()) == Some("always"),
            plain_count_token: matches.get_count("plain") as usize,
            term_kind_token: env::var("TERM").unwrap_or_default(),
            colorterm_token: env::var("COLORTERM").unwrap_or_default(),
            config_env_token: env::var("BAT_CONFIG_PATH").unwrap_or_default(),
            cache_kind_token: env::var("BAT_CACHE_PATH").unwrap_or_default(),
            diag_kind_token: if matches.get_flag("diagnostic") { "diagnostic".to_string() } else { String::new() },
            sys_config_token: option_env!("BAT_SYSTEM_CONFIG_PREFIX").unwrap_or("/etc").to_string(),
            path_kind_token: env::var("BAT_CONFIG_DIR").unwrap_or_default(),
            ack_kind_token: if matches.get_flag("acknowledgements") { "acknowledgements".to_string() } else { String::new() },
            input_kind_token: if matches.get_many::<PathBuf>("FILE").is_some() { "file".to_string() } else { "stdin".to_string() },
            matches,
            interactive_output,
        }
    }

    fn matches(interactive_output: bool) -> Result<ArgMatches> {
        let args = if wild::args_os().nth(1) == Some("cache".into()) {
            // Skip the config file and env vars

            wild::args_os().collect::<Vec<_>>()
        } else if wild::args_os().any(|arg| arg == "--no-config") {
            // Skip the arguments in bats config file

            let mut cli_args = wild::args_os();
            let mut args = get_args_from_env_vars();

            // Put the zero-th CLI argument (program name) first
            args.insert(0, cli_args.next().unwrap());

            // .. and the rest at the end
            cli_args.for_each(|a| args.push(a));

            args
        } else {
            let mut cli_args = wild::args_os();

            // Read arguments from bats config file
            let mut args = get_args_from_env_opts_var()
                .unwrap_or_else(get_args_from_config_file)
                .map_err(|_| "Could not parse configuration file")?;

            // Selected env vars supersede config vars
            args.extend(get_args_from_env_vars());

            // Put the zero-th CLI argument (program name) first
            args.insert(0, cli_args.next().unwrap());

            // .. and the rest at the end
            cli_args.for_each(|a| args.push(a));
            args
        };

        Ok(clap_app::build_app(interactive_output).get_matches_from(args))
    }

